(952, 10, 'h7lc1fdc3a8iocokm9d0q43ila', 'edit_property', '{\"property_id\":\"356\",\"changes\":[\"\\u062a\\u0645 \\u062a\\u063a\\u064a\\u064a\\u0631 \\u0627\\u0644\\u0639\\u0646\\u0648\\u0627\\u0646 \\u0645\\u0646: \\u0634\\u0642\\u0647 \\u0634\\u0627\\u0631\\u0639 \\u0627\\u0644\\u0633\\u0648\\u062f\\u0627\\u0646 \\u0625\\u0644\\u0649: \\u0634\\u0627\\u0631\\u0639 \\u0627\\u062d\\u0645\\u062f \\u062e\\u0634\\u0627\\u0628\",\"\\u062a\\u0645 \\u062a\\u063a\\u064a\\u064a\\u0631 \\u0627\\u0644\\u0648\\u0635\\u0641 \\u0645\\u0646: \\u0627\\u0644\\u062f\\u0648\\u0631 \\u0639\\u0644\\u0649 \\u0634\\u0642\\u062a\\u064a\\u0646  \\r\\n\\u0644\\u0627\\u064a\\u0648\\u062c\\u062f \\u0627\\u0633\\u0627\\u0646\\u0633\\u064a\\u0631 \\r\\n\\u0645\\u0633\\u062c\\u0644\\u0629 \\u0634\\u0647\\u0631 \\u0639\\u0642\\u0627\\u0631\\u0649 \\r\\n\\u064a\\u0648\\u062c\\u062f \\u062d\\u0635\\u0629 \\u0641\\u0649 \\u0627\\u0644\\u0627\\u0631\\u0636 \\r\\n\\u064a\\u0648\\u062c\\u062f \\u063a\\u0627\\u0632 \\u0637\\u0628\\u064a\\u0639\\u064a \\u0639\\u062f\\u0627\\u062f \\u0642\\u062f\\u064a\\u0645 \\r\\n\\u064a\\u0648\\u062c\\u062f \\u0639\\u062f\\u0627\\u062f \\u0627\\u0644\\u0643\\u0647\\u0631\\u0628\\u0627\\u0621 \\u0642\\u062f\\u064a\\u0645\\r\\n\\u0645\\u0635\\u0627\\u0631\\u064a\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0627\\u0631\\u0647 \\u0643\\u0644 \\u0634\\u0647\\u0631 \\u0634\\u0627\\u0645\\u0644 \\u0627\\u0644\\u0645\\u064a\\u0627\\u0647\\/ 200\\r\\n\\u0647\\u0634\\u0627\\u0645 (\\u0643\\u0627\\u0645\\u0628\\u064a\\u0646 ) \\u0625\\u0644\\u0649: \\u0627\\u0644\\u062f\\u0648\\u0631 \\u0639\\u0644\\u064a 3 \\u0634\\u0642\\u0642 \\r\\n\\u0627\\u0633\\u0627\\u0646\\u0633\\u064a\\u0631 \\r\\n\\u0644\\u0647 \\u062d\\u0635\\u0629 \\u0641\\u064a \\u0627\\u0644\\u0627\\u0631\\u0636 \\r\\n\\u0627\\u0648\\u0644 \\u0645\\u0627\\u0644\\u0643 \\u0648\\u0639\\u0642\\u062f \\u0646\\u0647\\u0627\\u0626\\u064a \\u0645\\u0627\\u0644\\u0643 \\u0627\\u0644\\u0639\\u0645\\u0627\\u0631\\u0629 \\r\\n\\u0627\\u0644\\u0633\\u0639\\u0631 \\u0634\\u0627\\u0645\\u0644 \\u0627\\u0644\\u0639\\u0641\\u0634 \\u0648\\u0627\\u0644\\u0627\\u062c\\u0647\\u0632\\u0629 \\r\\n\\u0627\\u0644\\u0633\\u0639\\u0631 \\u0642\\u0627\\u0628\\u0644 \\u0644\\u0644\\u062a\\u0641\\u0627\\u0648\\u0636\",\"\\u062a\\u0645 \\u062a\\u063a\\u064a\\u064a\\u0631 \\u0627\\u0644\\u0645\\u0648\\u0642\\u0639 \\u0645\\u0646: \\u0634\\u0627\\u0631\\u0639 \\u0627\\u0644\\u0633\\u0648\\u062f\\u0627\\u0646 \\u0627\\u0644\\u0631\\u0626\\u064a\\u0633\\u0649 \\u0623\\u0645\\u0627\\u0645 \\u0646\\u0632\\u0644\\u0647 \\u0627\\u0644\\u0643\\u0648\\u0628\\u0631\\u064a \\u0645\\u0627\\u0628\\u064a\\u0646 \\u0645\\u064a\\u062f\\u0627\\u0646 \\u0644\\u0628\\u0646\\u0627\\u0646  \\u0648 \\u0627\\u0631\\u0636 \\u0627\\u0644\\u0644\\u0648\\u0627\\u0621 \\u0625\\u0644\\u0649: \\u0634\\u0627\\u0631\\u0639 \\u0627\\u062d\\u0645\\u062f \\u062e\\u0634\\u0627\\u0628 \\u0628\\u062c\\u0648\\u0627\\u0631 \\u0627\\u0644\\u062d\\u062f\\u064a\\u0642\\u0629 \\u0627\\u0644\\u062f\\u0648\\u0644\\u064a\\u0629 \\u0645\\u0627\\u0628\\u064a\\u0646 \\u0639\\u0628\\u0627\\u0633 \\u0627\\u0644\\u0628\\u0639\\u0642\\u0627\\u062f \\u0648\\u0645\\u0643\\u0631\\u0645 \\u0639\\u0628\\u064a\\u062f\",\"\\u062a\\u0645\\u062a \\u0625\\u0636\\u0627\\u0641\\u0629 \\u0627\\u0644\\u0645\\u0633\\u0627\\u062d\\u0629: 165\",\"\\u062a\\u0645 \\u062a\\u063a\\u064a\\u064a\\u0631 \\u062a\\u0635\\u0645\\u064a\\u0645 \\u0627\\u0644\\u0648\\u062d\\u062f\\u0629 \\u0645\\u0646: \\u0664\\u063a\\u0631\\u0641\\u0629 +\\u062d\\u0645\\u0627\\u0645 +\\u0645\\u0637\\u0628\\u062e +\\u0631\\u064a\\u0633\\u0628\\u0634\\u064a\\u0646 \\u0642\\u0637\\u0639\\u062a\\u064a\\u0646 \\u0625\\u0644\\u0649: 3 \\u063a\\u0631\\u0641 + 2 \\u062d\\u0645\\u0627\\u0645\",\"\\u062a\\u0645 \\u062a\\u063a\\u064a\\u064a\\u0631 \\u0627\\u0644\\u0645\\u0646\\u0637\\u0642\\u0629 \\u0645\\u0646: \\u0634\\u0627\\u0631\\u0639 \\u0627\\u0644\\u0633\\u0648\\u062f\\u0627\\u0646 \\u0625\\u0644\\u0649: \\u0645\\u