(104, 1, 'شقه فيو نيل دقي', '1- ببرج مميز داخل شارع خاص (مغلق تامين) بجوار السفارة السعودية\r\n2-مسجله ولها حصة في الأرض \r\n3-شقة واحدة في الدور ١٣ بدون جار\r\n4-  شاملة تكييفات\r\n5-المداخل والاسانسيرات بتجدد كل ٥ سنين \r\n٢ اسانسير', '', 280.00, NULL, 'available', 'Resale', '2025-09-20 14:14:20', 7, '4 غرف + 5 حمام', 5, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'بجوار السفارة السعودية', 'الجيزه', '', 21, '1992', '13', NULL, NULL, 36000000.00, NULL, NULL, NULL, 'مالك', 'محمود', '01223439966', '', '', '', '', 0, 30.03181180, 31.22045020),
(105, 1, 'شقه حدايق الاهرام', '1- جانبى بحرى \r\n2-حصه بالأرض  - وجميع الخدمات متاحه 24 ساعة \r\n3- عداد كهرباء وأسانسير تحت التركيب \r\n4- الشقة تصلح سكني و استثماري', 'البوابه التانيه منطقه واو', 90.00, NULL, 'available', 'Resale', '2025-09-20 14:23:46', 7, 'غرفتين وحمام', 6, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'حدايق الاهرام', 'الجيزه', 'المصري للتسويق العقاري', NULL, '', 'دور اول', NULL, NULL, 1280000.00, NULL, NULL, NULL, 'شركة تسويق', 'محمد', '01055696234', '', '', '', '', 2, 29.96617300, 31.10862730),
