(383, 1, 'شارع الجزائر', 'الدور علي 3 شقق \r\nعداد غاز \r\nله حصة في الارض \r\nمسجلة شهر عقاري \r\n2 اسانسر \r\nالسعر شامل العفش والاجهزة \r\nالسعر قابل للتفاوض', '6 شارع الجزائر عمارة العمدة بجوار فندق اطلس وتطل علي نادي الزمالك', 300.00, NULL, 'available', 'Resale', '2025-12-07 12:07:21', 10, '3 غرف + 2 حمام', 4, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'المهندسين', 'الجيزه', '', 13, '', '13', NULL, NULL, 7300000.00, NULL, NULL, NULL, 'مالك', 'سليم', '01001257710', '', '', '', '', 0, 30.05718600, 31.20875900),
(384, 1, 'شارع محمد ابراهيم', 'الدور علي شقتين \r\nالشقة امامي \r\nعداد غاز قديم \r\nعداد كهرباء قديم \r\nالسعر قابل للتفاوض', 'شارع محمد ابراهيم متفرع من شارع المشروع ميته عقبه', NULL, NULL, 'available', 'Resale', '2025-12-07 12:51:00', 10, '3 غرف + حمام', 4, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'المهندسين', 'الجيزه', '', 5, '', 'الاول علوي', 60.00, NULL, 570000.00, NULL, NULL, NULL, 'مالك', 'احمد', '01140383300', '', '', '', '', 0, 30.06455900, 31.19973300),
(385, 1, 'كورنيش النيل المعادي', 'الدور علي شقتين \r\nصحة توقيع \r\nله حصة في الارض \r\nاسانسير \r\nعداد غاز \r\nالسعر شامل العفش والاجهزة \r\nالسعر قابل للتفاوض', 'كورنيش النيل المعادي بجوار كارفور', NULL, NULL, 'available', 'Resale', '2025-12-07 12:56:47', 10, '3 غرف + 2 حمام', 4, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'المعادي', 'القاهره', '', 12, '', '8', 135.00, NULL, 3300000.00, NULL, NULL, NULL, 'مالك', 'جاسي', '01102239017', '', '', '', '', 0, 29.95771000, 31.27391300),
(386, 1, 'شارع المرغي الرئيسي', 'الدور علي 5 شقق \r\nاسانسير \r\nعداد كهرباء قديم \r\nيصلح تركيب غاز بسهولة عشان العمارة داخله غاز \r\nالعمارة مراقبة بالكاميرات \r\nمسجلة شهر عقاري \r\nله حصة في الارض \r\nالسعر شامل العفش والاجهزة \r\nالسعر قابل للتفاوض \r\nسعر الايجار 18 الف', 'شارع المراغي الرئيسي في العجوزة امام مستشفي التاهيل للقوات المسلحة', NULL, NULL, 'available', 'Resale', '2025-12-07 13:09:09', 10, 'غرفتين وحمام', 4, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'العجوزة', 'الجيزه', '', 10, 'تسعينات', '4', 100.00, NULL, 2900000.00, NULL, NULL, NULL, 'مالك', 'مصطفي', '01000943616', '', '', '', '', 0, 30.05281100, 31.21846000),
(387, 1, 'شارع محمد موسي', 'الدور علي شقة واحدة \r\nلا يوجد اسانسير \r\nمسجلة شهر عقاري \r\nله حصة في الارض \r\nعداد غاز قديم \r\nعداد كهرباء قديم \r\nالبيع بدون العفش والاجهزة \r\nالسعر قابل للتفاوض \r\nالمعاينة يوم الجمعة والسبت فقط', 'شارع محمد موسي تاني نمرة من فيصل الرئيسي', NULL, NULL, 'available', 'Resale', '2025-12-07 13:16:36', 10, '3 غرف + حمام', 4, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'فيصل', 'الجيزه', '', 4, '', '2', 125.00, NULL, 1500000.00, NULL, NULL, NULL, 'مالك', 'يحي', '01012482779', '', '', '', '', 0, 30.01478100, 31.21798100),
(388, 1, 'شارع احمد خشاب', 'الدور علي شقتين \r\nاسانسير \r\nصحة توقيع \r\nله حصة في الارض \r\nالسعر قابل للتفاوض', 'شارع احمد خشاب متفرع من عباس العقاد امام الحديقة الدولية بين عباس العقاد ومكرم عبيد', 175.00, NULL, 'available', 'Resale', '2025-12-07 14:34:13', 10, '3 غرف + 2 حمام', 4, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'مدينة نصر', 'القاهره', '', 7, '2012', 'الارضي', NULL, NULL, 5500000.00, NULL, NULL, NULL, 'مالك', 'ياسمين', '01000220984', '', '', '', '', 0, 30.05076800, 31.34419400),
(389, 1, 'شارع الفريق عبود', 'الدور علي 4 شقق \r\nلا يوجد اسانسير \r\nله حصة في الارض \r\nصحة توقيع \r\nعداد غز طبيعي \r\nعداد كهرباء قديم \r\nالسعر قابل للتفاوض', 'شارع الفريق عبود متفرع من شارع شاهين', 140.00, NULL, 'available', 'Resale', '2025-12-07 14:48:25', 10, 'غرفتين وحمام', 4, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'العجوزة', 'الجيزه', '', 6, '', '5', NULL, NULL, 2500000.00, NULL, NULL, NULL, 'مالك', 'رشا', '01009722392', '', '', '', '', 0, 30.05348000, 31.21574000),
(390, 1, 'موازي لشارع نوال', 'الدور علي شقتين \r\nاسانسير \r\nعداد غاز \r\nله حصة في الارض \r\nصحة توقيع \r\nالسعر قابل للتفاوض', 'موازي لشارع نوال وشارع عبد العظيم راشد', 150.00, NULL, 'available', 'Resale', '2025-12-07 15:09:03', 10, 'غرفتين + 2 حمام', 4, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'العجوزة', 'الجيزه', '', 8, '', '6', NULL, NULL, 3800000.00, NULL, NULL, NULL, 'مالك', 'مهندس عبد الرحمن', '01153766255', '', '', '', '', 0, 30.04567100, 31.21629500),
(391, 1, 'شارع البصرة الرئيسي', 'الدور علي شقتين \r\nاسانسير \r\nله حصة في الارض \r\nصحة توقيع \r\nالعدادات باسم المالك \r\nغاز طبيعي السعر شامل العفش والاجهزة \r\nالسعر قابل للتفاوض', 'شارع البصرة الرئيسي', 150.00, NULL, 'available', 'Resale', '2025-12-07 15:41:21', 10, 'غرفتين + 2 حمام', 4, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'المهندسين', 'الجيزه', '', 6, '', '4', NULL, NULL, 4500000.00, NULL, NULL, NULL, 'مالك', 'ضياء', '01007077617', '', '', '', '', 0, 30.04957800, 31.19566700);
